INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('education', 'neet/physics', 'laws-of-motion', 'Newton''s Second Law of Motion states that the net force acting on a body equals:', '["Mass times acceleration (F = ma)", "Mass divided by velocity", "Mass times displacement", "Velocity divided by time alone"]', 0, 'Newton''s Second Law: the net force on an object is the product of its mass and its acceleration, F = ma.', 'beginner'),
('education', 'neet/physics', 'laws-of-motion', 'Newton''s Third Law states that for every action force, there is a reaction force that is:', '["Equal in magnitude and opposite in direction, acting on a different object", "Equal in magnitude and in the same direction", "Smaller in magnitude and opposite in direction", "Acting on the same object that exerted the action force"]', 0, 'Newton''s Third Law: forces occur in pairs, equal in magnitude and opposite in direction, each acting on a different object.', 'beginner'),
('education', 'neet/physics', 'laws-of-motion', 'The frictional force on an object generally acts in a direction that is:', '["Opposite to the direction of relative motion (or its tendency)", "Always in the same direction as motion", "Perpendicular to the direction of motion", "Independent of the direction of motion"]', 0, 'Friction opposes relative sliding (or the tendency to slide) between two surfaces in contact.', 'beginner'),
('education', 'neet/physics', 'laws-of-motion', 'For an object moving in a circle at constant speed, the net force on it is directed:', '["Toward the center of the circle (centripetal)", "Tangent to the circle, in the direction of motion", "Away from the center of the circle", "There is no net force acting on it"]', 0, 'Uniform circular motion requires a centripetal force directed toward the center, constantly changing the direction of velocity without changing its magnitude.', 'beginner'),
('education', 'neet/physics', 'laws-of-motion', 'Lami''s Theorem applies to a particle in equilibrium under three concurrent, coplanar forces, stating that each force is proportional to the:', '["Sine of the angle between the other two forces", "Cosine of the angle between the other two forces", "Sum of the other two forces", "Square of the angle between the other two forces"]', 0, 'Lami''s Theorem: for three concurrent forces keeping a particle in equilibrium, each force is proportional to the sine of the angle between the other two forces.', 'intermediate'),
('education', 'neet/physics', 'gravitation', 'Kepler''s Second Law (the Law of Areas) states that the line joining a planet to the sun sweeps out:', '["Equal areas in equal intervals of time", "Equal angles in equal intervals of time", "A constant area regardless of time elapsed", "Increasing areas as the planet speeds up uniformly"]', 0, 'Kepler''s Second Law describes how a planet moves faster when closer to the sun and slower when farther away, such that the swept area per unit time remains constant.', 'intermediate'),
('education', 'neet/physics', 'gravitation', 'The approximate escape velocity from Earth''s surface is:', '["11.2 km/s", "9.8 km/s", "7.9 km/s", "3.0 km/s"]', 0, 'Earth''s escape velocity is approximately 11.2 km/s, the minimum speed needed for an object to break free of Earth''s gravitational pull without further propulsion.', 'intermediate'),
('education', 'neet/physics', 'gravitation', 'The acceleration due to gravity at a point above Earth''s surface generally:', '["Decreases as altitude increases", "Increases as altitude increases", "Remains exactly constant at all altitudes", "Becomes negative above a certain altitude"]', 0, 'Since gravitational acceleration follows an inverse-square relationship with distance from Earth''s center, it decreases as altitude (and hence distance from the center) increases.', 'beginner'),
('education', 'neet/physics', 'gravitation', 'A geostationary satellite has an orbital time period of approximately:', '["24 hours", "90 minutes", "1 hour", "1 year"]', 0, 'A geostationary satellite orbits with the same period as Earth''s rotation (approximately 24 hours), allowing it to remain fixed above a specific point on the equator.', 'beginner'),
('education', 'neet/physics', 'gravitation', 'The approximate value of the universal gravitational constant G is:', '["6.674 x 10^-11 N.m^2/kg^2", "9.8 m/s^2", "3 x 10^8 m/s", "1.6 x 10^-19 C"]', 0, 'G, the universal gravitational constant appearing in Newton''s Law of Gravitation, has an experimentally determined value of approximately 6.674 x 10^-11 N.m^2/kg^2.', 'intermediate'),
('education', 'neet/physics', 'thermodynamics', 'The Zeroth Law of Thermodynamics establishes the concept of temperature by stating that:', '["If two systems are each in thermal equilibrium with a third system, they are in thermal equilibrium with each other", "Energy can neither be created nor destroyed", "Entropy of an isolated system never decreases", "Heat always flows from cold to hot spontaneously"]', 0, 'The Zeroth Law underlies the very concept of temperature measurement: mutual thermal equilibrium with a common reference (like a thermometer) implies thermal equilibrium between the two systems.', 'intermediate'),
('education', 'neet/physics', 'thermodynamics', 'The specific heat capacity of a substance is defined as the heat required to raise the temperature of:', '["A unit mass of the substance by one degree", "The entire sample by any amount", "One mole of the substance to its boiling point", "A unit volume of the substance by ten degrees"]', 0, 'Specific heat capacity is the amount of heat energy needed to raise the temperature of a unit mass of a substance by one degree (Celsius or Kelvin).', 'beginner'),
('education', 'neet/physics', 'thermodynamics', 'The efficiency of a Carnot engine depends only on:', '["The temperatures of the hot source and cold sink", "The specific working substance used", "The size of the engine", "The pressure of the surrounding atmosphere"]', 0, 'A key result of Carnot''s theorem: the efficiency of an ideal Carnot engine depends solely on the source and sink temperatures, independent of the working substance.', 'intermediate'),
('education', 'neet/physics', 'thermodynamics', 'During an isothermal process involving an ideal gas, the internal energy of the gas:', '["Remains constant, since internal energy depends only on temperature", "Always increases", "Always decreases", "Becomes zero"]', 0, 'For an ideal gas, internal energy is a function of temperature alone; since temperature is constant during an isothermal process, internal energy does not change.', 'intermediate'),
('education', 'neet/physics', 'thermodynamics', 'A heat engine is a device that converts:', '["Heat energy into mechanical work", "Mechanical work directly into mass", "Chemical energy into heat with no work output", "Electrical energy into heat only"]', 0, 'A heat engine operates in a cycle, absorbing heat from a hot reservoir and converting part of it into useful mechanical work, rejecting the rest to a cold reservoir.', 'beginner'),
('education', 'neet/physics', 'optics', 'The power of a lens is measured in units of:', '["Diopters (the reciprocal of focal length in meters)", "Watts", "Lumens", "Candela"]', 0, 'Lens power (P = 1/f, with f in meters) is measured in diopters, indicating how strongly the lens converges or diverges light.', 'beginner'),
('education', 'neet/physics', 'optics', 'Total Internal Reflection occurs when light travels from a denser medium to a rarer medium at an angle of incidence:', '["Greater than the critical angle", "Less than the critical angle", "Exactly equal to zero", "Equal to 90 degrees only"]', 0, 'Total Internal Reflection occurs only when light moves from a denser to a rarer medium and the angle of incidence exceeds the critical angle for that pair of media.', 'intermediate'),
('education', 'neet/physics', 'optics', 'Young''s Double Slit Experiment provides key evidence for the:', '["Wave nature of light (through interference patterns)", "Particle nature of light exclusively", "Speed of light being infinite", "Non-existence of light diffraction"]', 0, 'The alternating bright and dark fringes observed in Young''s Double Slit Experiment demonstrate constructive and destructive interference, a hallmark of light''s wave nature.', 'intermediate'),
('education', 'neet/physics', 'optics', 'The mirror formula relates the object distance (u), the image distance (v), and the:', '["Focal length (f) of the mirror", "Radius of the mirror''s frame", "Color of the incident light", "Height of the object only"]', 0, 'The mirror formula connects object distance, image distance, and focal length for spherical mirrors, a standard relation used to locate images.', 'beginner'),
('education', 'neet/physics', 'optics', 'When an object is placed within the focal length of a convex lens used as a magnifying glass, the image formed is:', '["Virtual, erect, and magnified", "Real, inverted, and diminished", "Real, erect, and the same size", "Virtual, inverted, and diminished"]', 0, 'A convex lens acting as a simple magnifier (object placed within its focal length) always produces a virtual, erect, and magnified image.', 'intermediate'),
('education', 'neet/physics', 'electrostatics-magnetism', 'Gauss''s Law relates the total electric flux through a closed surface to the:', '["Net electric charge enclosed within that surface", "Surface area of the closed surface alone", "Distance from the nearest charge", "Material the surface is made of"]', 0, 'Gauss''s Law states that the total electric flux through any closed surface is proportional to the net charge enclosed by that surface, regardless of the surface''s exact shape.', 'intermediate'),
('education', 'neet/physics', 'electrostatics-magnetism', 'The electric potential due to a point charge, as distance from the charge increases, generally:', '["Decreases", "Increases", "Remains constant", "Becomes negative regardless of charge sign"]', 0, 'Electric potential due to a point charge, V = kq/r, decreases in magnitude as the distance r from the charge increases.', 'beginner'),
('education', 'neet/physics', 'electrostatics-magnetism', 'Faraday''s Law of Electromagnetic Induction states that the induced EMF in a circuit is proportional to the:', '["Rate of change of magnetic flux through the circuit", "Total magnetic flux at any single instant", "Resistance of the circuit alone", "Length of the wire used in the circuit"]', 0, 'Faraday''s Law: the induced EMF equals the negative rate of change of magnetic flux linked with the circuit.', 'beginner'),
('education', 'neet/physics', 'electrostatics-magnetism', 'Lenz''s Law states that the direction of an induced current is such that it:', '["Opposes the change in magnetic flux that produced it", "Always reinforces the change in magnetic flux", "Has no defined relationship with the causing flux change", "Depends only on the resistance of the circuit"]', 0, 'Lenz''s Law is a statement of energy conservation: induced current always flows in a direction that opposes the change in flux causing it.', 'intermediate'),
('education', 'neet/physics', 'electrostatics-magnetism', 'A transformer operates based on the principle of:', '["Mutual electromagnetic induction between two coils", "Direct current flow through a single coil", "Permanent magnetism alone, with no changing flux", "Electrostatic attraction between charged plates"]', 0, 'A transformer uses mutual induction -- a changing current in the primary coil induces an EMF in the secondary coil via a shared, changing magnetic flux.', 'intermediate'),
('education', 'neet/chemistry', 'chemical-bonding', 'A molecule with sp hybridization at its central atom typically has which molecular geometry?', '["Linear (bond angle 180 degrees)", "Tetrahedral (bond angle ~109.5 degrees)", "Trigonal planar (bond angle 120 degrees)", "Octahedral (bond angle 90 degrees)"]', 0, 'sp hybridization involves two hybrid orbitals arranged linearly, giving a bond angle of 180 degrees.', 'intermediate'),
('education', 'neet/chemistry', 'chemical-bonding', 'Hydrogen bonding is primarily responsible for the unusually high boiling point of water compared to other Group 16 hydrides such as H2S:', '["True -- extensive hydrogen bonding between water molecules raises its boiling point significantly", "False -- water''s boiling point is actually lower than H2S", "False -- hydrogen bonding has no effect on boiling point", "True, but only because of water''s molecular mass"]', 0, 'Water''s small size and high electronegativity allow extensive intermolecular hydrogen bonding, giving it a much higher boiling point than heavier Group 16 hydrides like H2S, which cannot hydrogen bond as effectively.', 'intermediate'),
('education', 'neet/chemistry', 'chemical-bonding', 'An ionic bond typically forms between:', '["A metal (electropositive) and a non-metal (electronegative), via electron transfer", "Two non-metals, via electron sharing", "Two metals, via electron transfer", "Any two atoms, regardless of electronegativity difference"]', 0, 'Ionic bonds form when a highly electropositive metal transfers one or more electrons to a highly electronegative non-metal, creating oppositely charged ions that attract each other.', 'beginner'),
('education', 'neet/chemistry', 'chemical-bonding', 'Using Molecular Orbital Theory, the bond order of the nitrogen molecule (N2) is:', '["3", "2", "1", "0"]', 0, 'N2''s molecular orbital configuration gives 8 bonding and 2 antibonding electrons; bond order = (8-2)/2 = 3, consistent with its known triple bond.', 'intermediate'),
('education', 'neet/chemistry', 'chemical-bonding', 'Dipole moment is a vector quantity used to measure the:', '["Polarity of a bond or molecule", "Total mass of a molecule", "Number of covalent bonds in a molecule", "Boiling point of a compound directly"]', 0, 'Dipole moment quantifies the separation of positive and negative charge within a bond or molecule, indicating its degree of polarity.', 'beginner'),
('education', 'neet/chemistry', 'equilibrium', 'The relationship between Kp and Kc for a gaseous equilibrium reaction is given by:', '["Kp = Kc (RT)^(delta n)", "Kp = Kc / RT", "Kp = Kc + RT", "Kp and Kc are always numerically identical"]', 0, 'Kp = Kc(RT)^(delta n), where delta n is the change in moles of gas (products minus reactants), R is the gas constant, and T is temperature.', 'intermediate'),
('education', 'neet/chemistry', 'equilibrium', 'The common ion effect generally causes the solubility of a sparingly soluble salt to:', '["Decrease, when a common ion is added", "Increase, when a common ion is added", "Remain completely unchanged", "Become zero instantly regardless of concentration"]', 0, 'Adding a common ion shifts the solubility equilibrium (by Le Chatelier''s Principle) toward the solid phase, decreasing the salt''s solubility.', 'intermediate'),
('education', 'neet/chemistry', 'equilibrium', 'The solubility product (Ksp) is an equilibrium constant applicable to:', '["Sparingly soluble salts, describing equilibrium between the solid and its dissolved ions", "Highly soluble salts only", "Gaseous reactions exclusively", "Acid-base neutralization reactions only"]', 0, 'Ksp describes the equilibrium between an undissolved sparingly soluble salt and its constituent ions in a saturated solution.', 'intermediate'),
('education', 'neet/chemistry', 'equilibrium', 'A buffer solution resists significant change in pH primarily when small amounts of:', '["Acid or base are added to it", "Water alone are added to it", "Neutral salt are added to it", "Solid precipitate are added to it"]', 0, 'A buffer, typically a weak acid with its conjugate base (or vice versa), can neutralize small additions of strong acid or base, resisting large pH shifts.', 'beginner'),
('education', 'neet/chemistry', 'equilibrium', 'The pH of a solution with a hydrogen ion concentration [H+] of 10^-3 M is:', '["3", "10", "-3", "1000"]', 0, 'pH = -log[H+] = -log(10^-3) = 3.', 'intermediate'),
('education', 'neet/chemistry', 'organic-reaction-mechanisms', 'An SN1 reaction proceeds through a mechanism involving:', '["A carbocation intermediate, following first-order kinetics", "A single concerted step with no intermediate", "A carbanion intermediate exclusively", "Second-order kinetics dependent on both reactant and nucleophile"]', 0, 'SN1 (substitution nucleophilic unimolecular) reactions proceed via a two-step mechanism through a carbocation intermediate, with the rate depending only on the substrate concentration (first-order).', 'intermediate'),
('education', 'neet/chemistry', 'organic-reaction-mechanisms', 'An SN2 reaction is characterized by a single concerted step involving:', '["Backside attack by the nucleophile, with inversion of configuration", "Frontside attack, retaining configuration", "A stable carbocation intermediate", "No dependence on nucleophile concentration"]', 0, 'SN2 (substitution nucleophilic bimolecular) reactions occur in one concerted step, with the nucleophile attacking from the side opposite the leaving group, inverting the stereochemistry.', 'intermediate'),
('education', 'neet/chemistry', 'organic-reaction-mechanisms', 'Aldol condensation occurs between two molecules of aldehydes or ketones that each possess:', '["An alpha-hydrogen atom", "No alpha-hydrogen atom", "A halogen substituent only", "A nitrogen atom in the ring"]', 0, 'Aldol condensation requires at least one reactant with an alpha-hydrogen, which is removed (by base or acid catalysis) to form the nucleophilic enolate/enol that attacks the carbonyl carbon of the other molecule.', 'intermediate'),
('education', 'neet/chemistry', 'organic-reaction-mechanisms', 'The Cannizzaro reaction is a disproportionation reaction characteristic of aldehydes that:', '["Lack an alpha-hydrogen atom, under concentrated base", "Possess an alpha-hydrogen atom, under dilute acid", "Are aromatic exclusively", "Contain a halogen substituent only"]', 0, 'Aldehydes without an alpha-hydrogen (e.g. formaldehyde, benzaldehyde) cannot undergo aldol reactions; instead, under concentrated base, they undergo Cannizzaro disproportionation into an alcohol and a carboxylate salt.', 'intermediate'),
('education', 'neet/chemistry', 'organic-reaction-mechanisms', 'Benzene and other aromatic compounds characteristically undergo which type of reaction, preserving their aromatic ring?', '["Electrophilic Aromatic Substitution (EAS)", "Nucleophilic addition", "Electrophilic addition", "Free radical addition"]', 0, 'Aromatic compounds favor electrophilic substitution over addition, since substitution preserves the stable, delocalized aromatic pi system that addition would disrupt.', 'intermediate'),
('education', 'neet/chemistry', 'solutions-electrochemistry', 'Raoult''s Law states that the partial vapor pressure of a component in an ideal solution is proportional to its:', '["Mole fraction in the solution", "Molar mass", "Boiling point alone", "Density"]', 0, 'Raoult''s Law: the partial vapor pressure of each volatile component in an ideal solution equals its mole fraction times its pure vapor pressure.', 'beginner'),
('education', 'neet/chemistry', 'solutions-electrochemistry', 'The Van''t Hoff factor (i) is used to account for:', '["The degree of dissociation or association of a solute in solution", "The molar mass of the solvent only", "The temperature of the solution alone", "The color of the resulting solution"]', 0, 'The Van''t Hoff factor corrects colligative property calculations for solutes that dissociate (i>1) or associate (i<1) in solution, relative to ideal non-electrolyte behavior.', 'intermediate'),
('education', 'neet/chemistry', 'solutions-electrochemistry', 'The Nernst equation relates the electrode/cell potential of an electrochemical cell to the:', '["Concentrations (activities) of the species involved in the reaction", "Physical size of the electrodes only", "Color of the electrolyte solution", "Atmospheric pressure alone"]', 0, 'The Nernst equation adjusts the standard cell potential based on the actual concentrations (or activities) of the reacting ionic species, not just standard conditions.', 'intermediate'),
('education', 'neet/chemistry', 'solutions-electrochemistry', 'Faraday''s First Law of Electrolysis states that the mass of a substance deposited or liberated at an electrode is directly proportional to the:', '["Quantity of electric charge passed through the electrolyte", "Temperature of the electrolyte alone", "Color of the electrode", "Volume of the electrolyte solution"]', 0, 'Faraday''s First Law: the mass of substance produced at an electrode during electrolysis is directly proportional to the total charge (current x time) passed through the cell.', 'intermediate'),
('education', 'neet/chemistry', 'solutions-electrochemistry', 'The molar conductance of an electrolyte generally ___ upon dilution.', '["Increases", "Decreases", "Remains exactly constant", "Becomes zero immediately"]', 0, 'Dilution increases the degree of dissociation (for weak electrolytes) and reduces ionic interactions (for strong electrolytes), both of which increase molar conductance.', 'intermediate')
